WITH unpacked AS (SELECT id, plan, currency, tier_limits, tier_prices, SLICE(tier_limits, 1, 2) AS first_two_limits, ARRAY_MIN(tier_prices) AS lowest_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers WHERE currency = 'EUR') SELECT CASE WHEN entry_price >= 26 THEN 'PREMIUM' ELSE 'STANDARD' END AS entry_price_tier, COUNT_IF(currency = 'USD') AS usd_events, APPROX_PERCENTILE(lowest_price, ARRAY(0.25, 0.5, 0.75)) AS lowest_price_quartiles, PERCENTILE_APPROX(entry_price, 0.9) AS entry_price_p90, COUNT(*) FILTER (WHERE plan = 'basic') AS basic_rows FROM unpacked GROUP BY 1 HAVING COUNT_IF(currency = 'USD') < 1 ORDER BY entry_price_tier DESC;
